/**
 * Locales of the docs site (adr/0033). English is the only hand-written source
 * (src/routes/en); the other locales are generated by scripts/i18n/generate.ts.
 *
 * Plain TypeScript without imports: also read by the Node scripts.
 */
export const LOCALES = ['en', 'ja'] as const;

export type Locale = (typeof LOCALES)[number];

export const SOURCE_LOCALE: Locale = 'en';

/** Shown in the language switcher, in each language itself. */
export const LOCALE_NAMES: Record<Locale, string> = {
  en: 'English',
  ja: '日本語',
};

export function isLocale(value: string): value is Locale {
  return (LOCALES as readonly string[]).includes(value);
}

/** The locale of a pathname (`/ja/overview/` → `ja`), English when it has none. */
export function getLocale(pathname: string): Locale {
  const segment = pathname.split('/')[1] ?? '';
  return isLocale(segment) ? segment : SOURCE_LOCALE;
}

/** Removes the locale segment (`/ja/overview/` → `/overview/`). */
export function stripLocale(pathname: string): string {
  const segment = pathname.split('/')[1] ?? '';
  return isLocale(segment) ? pathname.slice(segment.length + 1) || '/' : pathname;
}

/**
 * Prefixes a site-relative href with the locale (`/overview/` → `/ja/overview/`).
 * External links, anchors and hrefs that already have a locale are returned as is.
 */
export function localizeHref(href: string, locale: Locale): string {
  if (!href.startsWith('/') || href.startsWith('//')) return href;
  if (isLocale(href.split('/')[1] ?? '')) return href;
  return `/${locale}${href}`;
}
